<template>
  <div class="research-workbench">
    <section class="research-hero">
      <div><div class="eyebrow">F081 · 科研美容板块</div><h1>科研美容案例台</h1><p>把产康与美容项目沉淀为可追踪的效果案例：方案、基线、复测、复核和归档一条链管理。</p></div>
      <div class="hero-actions"><el-tag effect="dark" type="warning">P0</el-tag><el-button type="primary" icon="el-icon-plus" @click="openDialog">新建案例</el-button></div>
    </section>

    <section class="metrics"><div v-for="metric in metrics" :key="metric.label" class="metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></div></section>

    <el-card shadow="never" class="filter-card">
      <div slot="header" class="card-head"><div><strong>案例检索</strong><small>按客户、项目类别和科研阶段筛选</small></div><el-button size="small" icon="el-icon-refresh" @click="loadRows">刷新</el-button></div>
      <el-form :inline="true" :model="filters" size="small">
        <el-form-item label="客户姓名"><el-input v-model="filters.customerName" clearable /></el-form-item>
        <el-form-item label="项目名称"><el-input v-model="filters.program" clearable /></el-form-item>
        <el-form-item label="类别"><el-select v-model="filters.category" clearable><el-option label="产康" value="产康" /><el-option label="美容" value="美容" /></el-select></el-form-item>
        <el-form-item label="案例状态"><el-select v-model="filters.status" clearable><el-option label="方案执行中" value="方案执行中" /><el-option label="需要复核" value="需要复核" /><el-option label="已完成" value="已完成" /></el-select></el-form-item>
        <el-form-item><el-button type="primary" icon="el-icon-search" @click="runSearch">查询</el-button><el-button @click="resetFilters">重置</el-button></el-form-item>
      </el-form>
    </el-card>

    <div class="research-grid">
      <el-card shadow="never" class="pipeline-card"><div slot="header" class="card-head"><div><strong>案例推进漏斗</strong><small>每个案例都有明确的下一步</small></div></div><div v-for="stage in pipeline" :key="stage.name" class="pipeline-stage"><div class="stage-title"><span class="stage-dot" :class="stage.tone" />{{ stage.name }}<b>{{ stage.rows.length }}</b></div><div v-for="row in stage.rows" :key="row.id" class="case-mini" @click="selectRow(row)"><strong>{{ row.customerName }}</strong><span>{{ row.program }}</span><em>{{ row.nextReview }}</em></div><div v-if="!stage.rows.length" class="empty-stage">暂无案例</div></div></el-card>

      <el-card shadow="never" class="case-card"><div slot="header" class="case-heading"><div><strong>效果案例库</strong><span>{{ filteredRows.length }} 条案例</span></div><el-button-group><el-button size="small" @click="exportRows">导出案例</el-button><el-button size="small" @click="printReport">打印摘要</el-button></el-button-group></div><el-table :data="filteredRows" border stripe height="520" highlight-current-row @current-change="selectRow" @row-dblclick="openDetails"><el-table-column type="index" width="48" label="#" /><el-table-column prop="caseNo" label="案例编号" width="135" /><el-table-column prop="customerName" label="客户" width="90" /><el-table-column prop="category" label="类别" width="70"><template slot-scope="scope"><el-tag size="mini" :type="scope.row.category === '产康' ? 'warning' : 'danger'">{{ scope.row.category }}</el-tag></template></el-table-column><el-table-column prop="program" label="方案项目" min-width="170" /><el-table-column prop="owner" label="负责人" width="90" /><el-table-column prop="baseline" label="基线" width="105" /><el-table-column prop="current" label="当前值" width="105" /><el-table-column prop="stage" label="科研阶段" width="110" /><el-table-column prop="status" label="状态" width="105"><template slot-scope="scope"><el-tag size="mini" :type="scope.row.status === '需要复核' ? 'warning' : scope.row.status === '已完成' ? 'success' : 'info'">{{ scope.row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template slot-scope="scope"><el-button type="text" @click="openDetails(scope.row)">查看</el-button><el-button type="text" @click="quickAction(scope.row)">下一步</el-button></template></el-table-column></el-table></el-card>
    </div>

    <el-drawer title="案例详情与复核" :visible.sync="drawerVisible" size="470px"><div v-if="selectedRow" class="drawer-content"><div class="case-title"><div class="case-badge">{{ selectedRow.category }}</div><div><h2>{{ selectedRow.customerName }}</h2><span>{{ selectedRow.caseNo }} · {{ selectedRow.program }}</span></div></div><el-alert v-if="selectedRow.status === '需要复核'" title="该案例等待医生复核后才可归档" type="warning" :closable="false" show-icon /><div class="measure-grid"><div><span>基线</span><strong>{{ selectedRow.baseline }}</strong></div><div><span>当前</span><strong>{{ selectedRow.current }}</strong></div><div><span>下次复测</span><strong>{{ selectedRow.nextReview }}</strong></div><div><span>风险等级</span><strong>{{ selectedRow.risk }}</strong></div></div><el-descriptions :column="1" border size="small"><el-descriptions-item label="负责人">{{ selectedRow.owner }}</el-descriptions-item><el-descriptions-item label="知情同意">{{ selectedRow.consent }}</el-descriptions-item><el-descriptions-item label="科研阶段">{{ selectedRow.stage }}</el-descriptions-item><el-descriptions-item label="案例状态">{{ selectedRow.status }}</el-descriptions-item></el-descriptions><div class="drawer-actions"><el-button type="primary" @click="quickAction(selectedRow)">{{ nextActionLabel }}</el-button><el-button @click="drawerVisible = false">关闭</el-button></div></div></el-drawer>

    <el-dialog title="新建科研美容案例" :visible.sync="dialogVisible" width="620px" :close-on-click-modal="false"><el-form :model="form" label-position="top"><el-row :gutter="16"><el-col :span="12"><el-form-item label="客户姓名" required><el-input v-model="form.customerName" /></el-form-item></el-col><el-col :span="12"><el-form-item label="房间号" required><el-input v-model="form.room" /></el-form-item></el-col><el-col :span="12"><el-form-item label="所属门店" required><el-select v-model="form.store" class="full-control"><el-option label="奇德芬芳·建设路店（中心店）" value="奇德芬芳·建设路店（中心店）" /><el-option label="奇德芬芳·黄河路店" value="奇德芬芳·黄河路店" /></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="项目类别" required><el-select v-model="form.category" class="full-control"><el-option label="产康" value="产康" /><el-option label="美容" value="美容" /></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="方案项目" required><el-input v-model="form.program" /></el-form-item></el-col><el-col :span="12"><el-form-item label="负责人" required><el-input v-model="form.owner" /></el-form-item></el-col><el-col :span="12"><el-form-item label="基线指标" required><el-input v-model="form.baseline" /></el-form-item></el-col><el-col :span="12"><el-form-item label="计划复测日" required><el-date-picker v-model="form.nextReview" class="full-control" type="date" value-format="yyyy-MM-dd" /></el-form-item></el-col><el-col :span="12"><el-form-item label="风险等级"><el-select v-model="form.risk" class="full-control"><el-option label="低" value="低" /><el-option label="中" value="中" /><el-option label="高" value="高" /></el-select></el-form-item></el-col></el-row></el-form><div slot="footer"><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="submitDialog">保存案例</el-button></div></el-dialog>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
import { getResearchModuleData, performResearchAction, saveResearchCase } from '@/api/erp-research'

const STORE_NAMES = {
  1: '奇德芬芳·建设路店（中心店）',
  2: '奇德芬芳·黄河路店'
}

export default {
  name: 'ResearchWorkbench',
  data() { return { rows: [], filters: { customerName: '', program: '', category: '', status: '' }, selectedRow: null, drawerVisible: false, dialogVisible: false, saving: false, form: {}} },
  computed: {
    ...mapGetters(['currentStoreId']),
    businessStoreId() { return String(this.currentStoreId || 'all') },
    isAllStores() { return this.businessStoreId === 'all' },
    businessStoreName() { return STORE_NAMES[Number(this.businessStoreId)] || '' },
    filteredRows() { const active = Object.keys(this.filters).filter(key => this.filters[key]); return this.rows.filter(row => active.every(key => String(row[key] || '').includes(String(this.filters[key])))) },
    metrics() { return [{ label: '执行中案例', value: this.rows.filter(row => row.status === '方案执行中').length, note: '持续观察', tone: 'purple' }, { label: '待复测', value: this.rows.filter(row => /复测/.test(row.stage)).length, note: '需要安排时段', tone: 'pink' }, { label: '待医生复核', value: this.rows.filter(row => row.status === '需要复核').length, note: '不可直接归档', tone: 'orange' }, { label: '已沉淀案例', value: this.rows.filter(row => row.status === '已完成').length, note: '可用于科研摘要', tone: 'green' }] },
    pipeline() { return [{ name: '方案执行中', tone: 'purple', rows: this.filteredRows.filter(row => row.status === '方案执行中') }, { name: '复测与观察', tone: 'pink', rows: this.filteredRows.filter(row => /复测|观察|跟进/.test(row.stage)) }, { name: '医生复核', tone: 'orange', rows: this.filteredRows.filter(row => row.status === '需要复核') }, { name: '归档案例', tone: 'green', rows: this.filteredRows.filter(row => row.status === '已完成') }] },
    nextActionLabel() { if (!this.selectedRow) return '选择案例'; if (this.selectedRow.status === '需要复核') return '提交复核'; if (this.selectedRow.status === '已完成') return '查看归档'; if (/复测/.test(this.selectedRow.stage)) return '安排复测'; return '记录跟进' }
  },
  watch: {
    '$route.fullPath': { immediate: true, handler() { this.loadRows() } },
    currentStoreId(value, previous) { if (String(value) !== String(previous)) this.loadRows() }
  },
  methods: {
    async loadRows() { try { const response = await getResearchModuleData({ ...this.filters, storeId: this.businessStoreId }); this.rows = response.data && response.data.list ? response.data.list : [] } catch (error) { this.$message.error('科研美容案例加载失败') } },
    runSearch() { this.loadRows() }, resetFilters() { this.filters = { customerName: '', program: '', category: '', status: '' }; this.loadRows() }, selectRow(row) { this.selectedRow = row }, openDetails(row) { this.selectedRow = row; this.drawerVisible = true },
    openDialog() { if (this.isAllStores) return this.$message.warning('全部门店仅支持汇总查询，请先在顶栏选择具体门店'); this.form = { category: '产康', risk: '低', store: this.businessStoreName, storeId: this.businessStoreId }; this.dialogVisible = true },
    async submitDialog() { if (this.isAllStores) return this.$message.warning('全部门店仅支持汇总查询，请先在顶栏选择具体门店'); const required = ['customerName', 'room', 'store', 'category', 'program', 'owner', 'baseline', 'nextReview']; if (required.some(key => !this.form[key])) return this.$message.warning('请填写完整的案例信息'); this.saving = true; try { const row = { ...this.form, storeId: this.businessStoreId, current: '待复测', stage: '方案待执行', consent: '待签署', status: '待制定方案' }; await saveResearchCase(row); this.dialogVisible = false; await this.loadRows(); this.$message.success('案例已保存，下一步请签署知情同意并制定方案') } catch (error) { this.$message.error('保存失败，请稍后重试') } finally { this.saving = false } },
    async quickAction(row) { if (!row || this.nextActionLabel === '查看归档') return this.$message.info('该案例已归档，可用于科研摘要'); if (this.isAllStores) return this.$message.warning('全部门店仅支持汇总查询，请先在顶栏选择具体门店'); const action = row.status === '需要复核' ? '提交复核' : /复测/.test(row.stage) ? '安排复测' : '记录跟进'; const rowId = row.id; try { await performResearchAction(action, { id: rowId, storeId: row.storeId || this.businessStoreId }); const current = this.rows.find(item => item.id === rowId); if (current && action === '安排复测') current.stage = '复测已预约'; if (current && action === '提交复核') current.status = '待医生复核'; if (current && action === '记录跟进') current.stage = '跟进中'; this.$message.success(`${action}已完成`) } catch (error) { this.$message.error('状态流转失败') } },
    exportRows() { const headers = ['案例编号', '客户', '类别', '方案项目', '负责人', '基线', '当前值', '阶段', '状态']; const body = this.filteredRows.map(row => [row.caseNo, row.customerName, row.category, row.program, row.owner, row.baseline, row.current, row.stage, row.status].map(value => `"${String(value || '').replace(/"/g, '""')}"`).join(',')); const blob = new Blob([`\uFEFF${headers.join(',')}\n${body.join('\n')}`], { type: 'text/csv;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = '科研美容案例库.csv'; link.click(); URL.revokeObjectURL(link.href) }, printReport() { window.print() }
  }
}
</script>

<style lang="scss" scoped>
