er; gap: 7px; color: #6c5364; font-size: 13px; }.stage-title b { margin-left: auto; color: #8d6178; }.stage-dot { width: 8px; height: 8px; border-radius: 50%; }.stage-dot.purple { background: #9362a8; }.stage-dot.pink { background: #cf6c9b; }.stage-dot.orange { background: #d99755; }.stage-dot.green { background: #66a783; }.case-mini { display: grid; grid-template-columns: 70px 1fr; gap: 3px 8px; margin-top: 9px; padding: 9px 10px; border-radius: 8px; cursor: pointer; background: #fcf8fa; }.case-mini:hover { background: #f8eaf1; }.case-mini strong { color: #593b51; font-size: 12px; }.case-mini span { color: #977f8f; font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.case-mini em { grid-column: 2; color: #b08e9f; font-size: 10px; font-style: normal; }.empty-stage { padding: 12px 10px; color: #c2adb8; font-size: 12px; }.case-heading { margin-bottom: 15px; }.case-heading > div { display: flex; align-items: baseline; gap: 10px; }.case-heading span { color: #aa94a2; font-size: 12px; }.case-card ::v-deep .el-table th { color: #66445c; background: #fcf4f8; }.drawer-content { padding: 0 22px 26px; }.case-title { display: flex; align-items: center; gap: 12px; margin-bottom: 18px; }.case-badge { display: grid; width: 44px; height: 44px; border-radius: 12px; color: #fff; background: #a85f81; place-items: center; font-size: 13px; }.case-title h2 { margin: 0 0 4px; color: #563b50; font-size: 19px; }.case-title span { color: #a08b98; font-size: 12px; }.measure-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; margin: 18px 0; }.measure-grid div { padding: 12px; border-radius: 8px; background: #fbf2f6; }.measure-grid span, .measure-grid strong { display: block; }.measure-grid span { color: #a18d9a; font-size: 11px; }.measure-grid strong { margin-top: 4px; color: #754a68; font-size: 16px; }.drawer-actions { margin-top: 18px; }.full-control { width: 100%; }
@media (max-width: 1050px) { .research-grid { grid-template-columns: 1fr; }.pipeline-card { display: none; }.metrics { grid-template-columns: repeat(2, 1fr); } } @media (max-width: 700px) { .research-workbench { padding: 12px; }.research-hero { align-items: flex-start; flex-direction: column; }.metrics { grid-template-columns: 1fr 1fr; }.filter-card ::v-deep .el-input, .filter-card ::v-deep .el-select { width: 100%; }.case-heading { align-items: flex-start; flex-direction: column; } }
</style>
